const fs = require('fs');
const path = require('path');

const baseDir = path.join(__dirname, '..', '거래 자료');
const masterCsv = fs.readFileSync(path.join(baseDir, '거래처 마스터.csv'), 'utf8');
const txCsv = fs.readFileSync(path.join(baseDir, '거래 내역.csv'), 'utf8');

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  const header = lines[0].split(',');
  return lines.slice(1).map(line => {
    const cols = line.split(',');
    const row = {};
    header.forEach((h, i) => { row[h] = cols[i]; });
    return row;
  });
}

const master = parseCsv(masterCsv);
const tx = parseCsv(txCsv);

const masterMap = new Map(master.map(m => [m.vendor_code, m.vendor_name]));

let totalAmount = 0;
let matchedRows = 0;
const unmapped = [];
const totalsByVendor = new Map();

for (const row of tx) {
  const code = row.vendor_code;
  const amount = Number(row.amount_krw);
  if (!masterMap.has(code)) {
    unmapped.push({ vendor_code: code, amount_krw: amount });
    continue;
  }
  matchedRows += 1;
  totalAmount += amount;
  const prev = totalsByVendor.get(code) || 0;
  totalsByVendor.set(code, prev + amount);
}

const vendorTotals = Array.from(totalsByVendor.entries())
  .map(([code, sum]) => ({ vendor_code: code, vendor_name: masterMap.get(code), total_krw: sum }))
  .sort((a, b) => a.vendor_code.localeCompare(b.vendor_code));

const result = {
  master_rows: master.length,
  tx_rows: tx.length,
  matched_rows: matchedRows,
  unmapped_rows: unmapped.length,
  unmapped,
  vendor_totals: vendorTotals,
  grand_total_krw: totalAmount,
};

console.log(JSON.stringify(result, null, 2));

